/**
 * Apply a voucher to an invoice. A voucher is a fixed amount discount applied after VAT.
 * Only one voucher per invoice, and only on draft invoices.
 * @param {{ status: string, voucher?: object }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check draft status
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check no voucher already exists
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

