test('createInvoice EOM handles end of month', () => {
  // February should be last day 28 or 29
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
