  // subtotal = 30000
  // line 1 vat = 10000 * 21 / 100 = 2100
  // line 2 vat = 10000 * 9 / 100 = 900
  // line 3 vat = 0
  // vat = 3000
  // total = 30000 + 3000 = 33000
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.vat, 3000);
  assert.equal(totals.total, 33000);
});

