test('lineVat calculates VAT on discounted amount', () => {
  // 100 cents, no discount, 21% VAT = 21 cents
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 0 }), 21);

  // 100 cents, 10% discount (10 cents off), 90 cents taxable, 21% = 18.9 -> 19 cents
  assert.equal(lineVat({ qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 10 }), 19);

  // 0% VAT
  assert.equal(lineVat({ qty: 5, unitPrice: 9500, vatRate: 0 }), 0);
});

test('lineVat with undefined discountPercent', () => {
