test('invoiceTotals calculates discount', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 5 * 9500 = 47500
  // discount = 47500 * 10 / 100 = 4750
  // amount after discount = 47500 - 4750 = 42750
  // vat = 42750 * 21 / 100 = 8977.5 -> 8978
  // total = 47500 - 4750 + 8978 = 51728
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 8978);
  assert.equal(totals.total, 51728);
});

test('invoiceTotals with multiple lines applies discount to each', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 9500, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // line 1: 3 * 9500 = 28500, discount = 2850, amount = 25650, vat = 5386.5 -> 5387
  // line 2: 1 * 120000 = 120000, discount = 6000, amount = 114000, vat = 23940
  // subtotal = 148500, discount = 8850, vat = 5387 + 23940 = 29327
  // But: 5386.5 + 23940 = 29326.5 which rounds to 29326 (banker's rounding)
  // total = 148500 - 8850 + 29326 = 168976
  assert.equal(totals.subtotal, 148500);
  assert.equal(totals.discount, 8850);
  assert.equal(totals.vat, 29326);
  assert.equal(totals.total, 168976);
});

test('invoiceTotals clamps total at 0 if discount exceeds subtotal', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, discountPercent: 150, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100
  // discount = 150 (would be 150, but clamped per line to 100)
  // amount = 100 - 100 = 0
  // vat = 0
  // total = max(0, 100 - 100 + 0) = 0
  assert.equal(totals.total, 0);
});

